if (b.length == n) {
    return true;
}

if (n == 0) {
    deallocate(p, data, max_size, b);
    return true;
}

const auto alignedLength = round_to_alignment(alignment, n);

if (!b) {
    b = allocate(p, data, max_size, alignment, n);
    return b.ptr != nullptr;
}

if (is_last_used_block(data, p, b)) {
    if (static_cast<char*>(b.ptr) + alignedLength <= p + (max_size - data)) {
        b.length = alignedLength;
        p = static_cast<char*>(b.ptr) + alignedLength;
        return true;
    }
    return false; // out of memory
}

if (b.length > n) {
    b.length = round_to_alignment(alignment, n);
    return true;
}

block new_block = allocate(p, data, max_size, alignment, n);
if (new_block.ptr) {
    std::memcpy(new_block.ptr, b.ptr, std::min(b.length, new_block.length));
    deallocate(p, data, max_size, b);
    b = new_block;
    return true;
}

return false;

